{
  "schema": "psop.mounting.knowledge/1.2-draft.1",
  "device_id": "microduck",
  "provenance": {
    "kind": "user_statement",
    "recorded_at": "2026-11-06",
    "statement": "应该有8个可安装孔位 并说明至少同侧两个相邻的孔位可作为安装接口 同时还要标识那两个孔位与腿部连杆的孔位相连接",
    "interpretation": "按用户前述说明，XL330 壳体两侧各四个孔位，标准参考装配使用同侧两个孔位连接腿部连杆。此交付将相邻显式解释为矩形边，保留 16 mm 短边与 30 mm 长边，排除对角；这是可复审的项目解释，不是厂家认证。本文件不指定螺纹、允许旋入深度、紧固扭矩或实际接合状态。"
  },
  "interface_families": [
    {
      "id": "xl330-housing-mount",
      "selector": {
        "mesh_key": "xl330",
        "geometry_sha256": "96238ed0d020ce0009cf1a5aa4b6926176c800840318ee65e4375be2298d2744"
      },
      "layout": {
        "type": "rectangular",
        "hole_diameter_m": 0.002,
        "spacing_m": [
          0.016,
          0.03
        ],
        "side_count": 2
      },
      "mechanism": "fastener_mount",
      "role": "housing_mount",
      "selection": {
        "same_side": true,
        "min_count": 2,
        "require_adjacent_pair": true,
        "adjacency": "rectangle_edges"
      },
      "statement": "A、B 两侧各四个可寻址安装孔位。一次安装选择同一侧至少两个成员，并包含矩形边上的一对相邻孔位；16 mm 短边与 30 mm 长边分别保留，不将对角线当成邻接。额外选孔仍须与对端、连接件和共同安装位姿相容。"
    }
  ],
  "reference_assemblies": [
    {
      "id": "xl330-leg-standard",
      "interface_family_ref": "xl330-housing-mount",
      "counterpart_selector": {
        "mesh_key": "leg",
        "geometry_sha256": "9a91cc1ae31ecd9e0c1ba93f3bb2ad8a12e29bff24ec27d1ac66c0c3037d9fcf"
      },
      "occurrence_selector": "same_source_body",
      "counterpart": {
        "hole_diameter_m": 0.0024,
        "hole_spacing_m": 0.016
      },
      "expected_pair_count": 2,
      "role": "bracket_mount",
      "statement": "在来源 qpos0 的标准参考装配中，与腿部连杆同属所指定来源 body 的 XL330 壳体采用同侧两个相邻孔位连接该连杆。共同来源 body 仅限定本条用户声明的实例范围，不自动证明其他同 body 部件之间存在物理连接。具体孔位映射由两孔孔距、共同参考位姿和孔轴对应复核；螺钉实体、允许长度、螺纹、保持状态及装配路径未在本说明中指定。"
    }
  ],
  "mounting_assertions": [
    {
      "id": "leg-upper-four-mounting-sites",
      "label": "连杆上端四孔安装位",
      "provenance": {
        "kind": "user_statement",
        "recorded_at": "2026-11-06",
        "statement": "腿部连杆上方的四个安装孔位没有识别出来",
        "interpretation": "用户指出上端四个孔是安装位置。源网格实测为四条直径 2.2 mm 的孔道、PCD 12 mm。仅将正 X 方向完整入口作为本次四个可寻址安装位置，依据是该入口朝向参考上方舵机近面；另一侧入口及非平齐扩孔保留几何身份。本说明未推定双向均可安装，未给出最少孔数、四孔必选、螺钉或输出活动框架。"
      },
      "selectors": [
        {
          "mesh_key": "leg",
          "geometry_sha256": "9a91cc1ae31ecd9e0c1ba93f3bb2ad8a12e29bff24ec27d1ac66c0c3037d9fcf"
        }
      ],
      "layout": {
        "type": "circular",
        "member_count": 4,
        "hole_diameter_m": 0.0022,
        "pitch_circle_diameter_m": 0.012,
        "entry_side": "positive_axis"
      },
      "mechanism": "unknown",
      "role": "bracket_mount",
      "selection": {
        "status": "unknown"
      },
      "statement": "上端四个安装位置独立寻址；PCD 分组仅说明几何组织。源 qpos0 与邻近舵机的四孔相位相差 45 度，不发布已对齐或已装配。未知选用规则不构成永久排除其他合理安装方式。",
      "assertion_basis": "user_statement"
    },
    {
      "id": "thigh-integral-mounting-pins",
      "label": "大腿一体锥柱安装定位位",
      "provenance": {
        "kind": "user_statement",
        "recorded_at": "2026-11-06",
        "statement": "右大腿部件的安装接口没有识别出来",
        "interpretation": "保留用户指出右大腿接口漏项的原始陈述；后续讨论不作为工程确认。源几何复核表明四根一体锥柱分成两对，各对约 16 mm 间距，分别对应同侧两台舵机的 B2/B3 壳体孔。来源零位下约插入 2 mm，入孔段约直径 1.80 至 1.59 mm，对应来源孔约直径 2 mm，模型显示正径向间隙而非过盈。把这解释为安装定位用途仍是 project_inferred，不能推定抗拔保持、承载或完整固定。外侧直径 5.5 mm 圆洞仅保留几何及未知用途，既不认定装饰孔，也不纳入小柱安装定位依据。厂家轴心螺钉／压盖图只能提供未验证替代示意，不能证明本设备实际采用。"
      },
      "selectors": [
        {
          "mesh_key": "upper_leg_right",
          "geometry_sha256": "5caf996cc3e151b01f393cdc6a6a6a940c1d86179d8b7c7f5f85cf1f1ac2fb63"
        },
        {
          "mesh_key": "upper_leg_left",
          "geometry_sha256": "8cb1c12dfa6d366a318bb1ec16f585427b9a185afeb7738d0a6f41f5db46a07d"
        }
      ],
      "layout": {
        "type": "linear_pins",
        "member_count": 2,
        "tip_diameter_m": 0.00159037,
        "pin_spacing_m": 0.016
      },
      "mechanism": "unknown",
      "role": "mounting_feature",
      "selection": {
        "status": "unknown"
      },
      "statement": "保留四根实体锥柱和同台壳体两孔的一对一来源配合；每对参考组只描述实测对应，不定义最少孔数或允许使用集合。仅支持安装定位用途推断，保持、载荷、选用规则及完成状态未知；外侧大圆洞不属于该小柱定位组，轴心固定件只属于待验证替代方案。",
      "assertion_basis": "project_inference"
    }
  ],
  "supporting_documents": [
    {
      "id": "SRC-MD-XL330-ASSEMBLY-INCLUDE",
      "title": "ROBOTIS X330 装配图入口",
      "path": "references/xl330-assembly/x330_drawing.md",
      "url": "https://raw.githubusercontent.com/ROBOTIS-GIT/emanual/0807b1b5f7472bbbbb2c9751f1d3406678e86d37/_includes/en/dxl/drawing/x330_drawing.md",
      "sha256": "ea5859ff3975edf15a823a8f4c9f8ba6adcdc9981a65f8b219641a9950f67740",
      "scope": "manufacturer_general",
      "claims": [
        "manufacturer_x330_assembly_diagram_index"
      ]
    },
    {
      "id": "SRC-MD-XL330-ASSEMBLY-DRAWING",
      "title": "ROBOTIS XL330 壳体及随动端装配图",
      "path": "references/xl330-assembly/xl330_assembly_integrated.png",
      "url": "https://raw.githubusercontent.com/ROBOTIS-GIT/emanual/0807b1b5f7472bbbbb2c9751f1d3406678e86d37/assets/images/dxl/x/x330/xl330_assembly_integrated.png",
      "sha256": "f24a151e24ae979e436ea33888863c8de2ed5f81955a096e1d2fa494d59ae217",
      "scope": "manufacturer_general",
      "claims": [
        "frame_front_and_back_use_m2_tapping_screws",
        "idler_assembly_has_idler_horn_idler_cap_and_m2_6x6_tapping_screw",
        "manufacturer_general_not_microduck_assembly_confirmation"
      ]
    },
    {
      "id": "SRC-MD-XL330-HORN-SCREW",
      "title": "ROBOTIS X330 舵盘螺钉长度示意",
      "path": "references/xl330-assembly/x330_horn_screw.png",
      "url": "https://raw.githubusercontent.com/ROBOTIS-GIT/emanual/0807b1b5f7472bbbbb2c9751f1d3406678e86d37/assets/images/dxl/x/x330/x330_horn_screw.png",
      "sha256": "0b25105a72e0506a55806438dee7c831530580e0257dfddf0e4000c6021c06f7",
      "scope": "manufacturer_general",
      "claims": [
        "horn_screw_diagram_contrasts_m2x6_tap_with_m2x8_tap_under_depicted_3T_geometry",
        "manufacturer_general_not_microduck_fastener_specification"
      ]
    }
  ],
  "connection_review": {
    "proximity_threshold_m": 0.002,
    "axis_alignment_tolerance_m": 2e-05,
    "statement": "看到这两个圆洞了吗 我觉得是与舵机固定用的\n你识别的两个有限面重叠投影 不太对\n这个爆炸图 应该把固定螺丝之类的也画进去\n接口这部分 需要重新仔细任意两个相接的部件\n你理解我的意思吗？",
    "manufacturer_source_refs": [
      "SRC-MD-XL330-ASSEMBLY-INCLUDE",
      "SRC-MD-XL330-ASSEMBLY-DRAWING",
      "SRC-MD-XL330-HORN-SCREW"
    ],
    "schematic_policy": "illustrative_unconfirmed"
  }
}

{
    "url": "https://cad.onshape.com/documents/804927696f06d877f3f1803e/w/5b75db19292e71970de02dee/e/ef6e972847fec8d82570b35e",
    "outputFormat": "mujoco",
    "robot_name": "microduck",
    "output_filename": "robot_walk",
    "simplify_stls": true,
    "max_stl_size": 1.0,
    "ignore": {
        "*": "collision",
        "!sole_left": "collision",
        "!sole_right": "collision",
        "!leg": "collision",
        "!power_support": "collision"
    },
    "additional_xml": [
        "joints_properties.xml",
        "sensors.xml",
        "additional.xml"
    ],
    "post_import_commands": [
        "sed -i 's/body name=\"trunk_base\" pos=\"[^\"]*\"/body name=\"trunk_base\" pos=\"0 0 0.12\"/' robot_walk.xml",
        "sed -i '/<!-- Part sole_left -->/{n; n; s/class=\"collision\"/name=\"left_foot_collision\" class=\"collision\"/}' robot_walk.xml",
        "sed -i '/<!-- Part sole_right -->/{n; n; s/class=\"collision\"/name=\"right_foot_collision\" class=\"collision\"/}' robot_walk.xml",
        "sed -i '/<!-- Part leg -->/{n; n; s/class=\"collision\"/class=\"self_collision_only\"/}' robot_walk.xml",
        "sed -i '/<!-- Part leg_2 -->/{n; n; s/class=\"collision\"/class=\"self_collision_only\"/}' robot_walk.xml",
        "sed -i '/<!-- Part power_support -->/{n; n; s/class=\"collision\"/class=\"self_collision_only\"/}' robot_walk.xml",
        "sed -i 's/ inheritrange=\"1\"//g' robot_walk.xml",
        "sed -i 's|<site[^>]*name=\"head_camera\"[^>]*pos=\"\\([^\"]*\\)\"[^>]*/>|&\\n              <camera name=\"head_camera\" pos=\"\\1\" quat=\"0 0 -1 0\"/>|' robot_walk.xml"
    ],
    "joint_properties": {
        "default": {
            "class": "chosen_actuator"
        },
        "passive*": {
          "actuated": false,
          "class" : "passive_joint"
        }
    }
}
